// Original written-exam problems. Platform problems live in exam-challenges.js.
import {expansionChoices,expansionWritten} from './linux-expansion.js';
export const examChoices=[];
export const writtenQuestions=[];
// Append the new topic bank after existing entries to keep existing order stable.
function M(id,lesson,prompt,code,options,steps,level='进阶'){
  examChoices.push({id:'exam-'+id,lesson,prompt,code,options,answer:0,steps,explain:steps.join('\n'),difficulty:level,source:'原创笔试题'});
}
function W(id,lesson,kind,title,prompt,code,answer,steps,rubric,level='进阶'){
  writtenQuestions.push({id:'written-'+id,lesson,kind,title,prompt,code,answer,steps,rubric,difficulty:level,source:'原创笔试题'});
}
M('ptr-post','c-pointer','执行完三行语句后，x、y、*p 分别是多少？每个表达式是独立语句。','int a[] = {4, 7, 9};\nint *p = a;\nint x = *p++;\nint y = ++*p;', ['4、8、8','7、8、9','4、5、7','7、9、9'],['*p++ 按 *(p++) 解释：先取得旧 p 所指的 4，再把 p 移到 a[1]。','++*p 按 ++(*p) 解释：把 a[1] 从 7 加到 8；p 本身不变。','最终 x=4，y=8，*p=8。把 ++ 作用在值上和作用在指针上混淆，会得到其余错误结果。']);
M('array-size','c-array','假设 int 4 字节、指针 4 字节，下面两处元素数量计算分别得到什么？','void f(int a[6]) {\n    size_t inside = sizeof(a) / sizeof(a[0]);\n}\nint a[6];\nsize_t outside = sizeof(a) / sizeof(a[0]);',['inside=1，outside=6','inside=6，outside=6','inside=1，outside=1','无法编译'],['函数形参 int a[6] 会调整成 int *a，方括号里的 6 不会把整个数组传入。','函数内 sizeof(a)=4，sizeof(a[0])=4，所以 inside=1。','外部 a 是真正的六元素数组，24/4=6。若指针改成 8 字节，inside 会变成 2；这不是通用求长方法。']);
M('matrix','c-array-pointer','假设 int 4 字节，求表达式的值与 p+1 相对 p 的字节偏移。','int a[2][3]={{2,4,6},{8,10,12}};\nint (*p)[3]=a;\nint x=*(*(p+1)+2);',['x=12，偏移12','x=6，偏移4','x=12，偏移4','x=10，偏移8'],['p 指向一整行，目标类型为 int[3]；因此 p+1 跨过 3×4=12 字节。','*(p+1) 选中第二行，该行在加法中转换为指向首元素的指针；再 +2 到第二行第三项。','最后的 * 读取 12。不能把指向数组的指针当成 int **；它们的目标类型与布局不同。']);
M('string-zero','c-string','以下 size_t 变量 n、m、k 分别为多少？','char s[]="ab\\0cd";\nsize_t n=sizeof(s);\nsize_t m=strlen(s);\nsize_t k=sizeof("ab\\0cd");',['6、2、6','5、2、5','6、5、6','2、2、2'],['数组含 a、b、显式 \\0、c、d、编译器追加的结尾 \\0，一共 6 个 char。','strlen 从起点读到第一个零字符就停，所以只数 a 和 b，结果 2。','sizeof 字符串字面量计算整个数组，包含结尾零字符。其余选项混淆了存储空间与字符串长度。']);
M('padding','c-struct','按给定 ABI：char 大小/对齐为1，int为4，short为2；无打包。offsetof(S,b)、offsetof(S,c)、sizeof(S) 是？','struct S { char a; int b; short c; };',['4、8、12','1、5、7','4、8、10','4、6、8'],['a 占偏移 0；b 需在 4 的倍数开始，因此偏移 1～3 是填充，b 从 4 开始占到 7。','c 对齐 2，从偏移 8 开始占到 9。结构体整体对齐为最大成员对齐 4。','总长度 10 还需向上补齐为 12，才能让结构体数组中下一项的 b 保持对齐。成员大小相加只有 7，不能代替布局推导。']);
M('unsigned','c-conversion','设 int、unsigned int 都是 32 位，UINT_MAX=4294967295。r 为多少？','int x=-2;\nunsigned int y=1;\nint r=(x<y);',['0','1','-1','比较本身必然未定义'],['相同转换等级的 signed int 与 unsigned int 运算时，int 被转换成 unsigned int。','-2 按模 2^32 转换得到 4294967294，大于 1，因此比较为假，即 0。','该无符号转换有定义；不能因为有负数就断言未定义，也不能按数学整数直接比较。']);
M('macro','c-macro','仅考虑这段无副作用的表达式，x 为多少？',' #define SQR(x) x*x\nint x=SQR(1+2);',['5','9','6','3'],['预处理器只替换 token，不会自动给实参加括号：展开为 1+2*1+2。','乘法优先于加法，得到 1+2+2=5。','可写为 ((x)*(x)) 修复优先级，但 SQR(i++) 仍重复求值，不能靠括号解决副作用问题。']);
M('unsequenced','c-ub','C11 下最准确的判断是？','int i=1;\nint x=i++ + ++i;',['未定义行为，不能推出可靠的 x','x 一定是4','x 一定是5','仅由 int 字节数决定'],['两个操作数都修改 i，而 + 不规定它们之间的先后顺序。','对同一标量的两次修改没有必要的先后约束，因此属于未定义行为。','观察某次编译输出不能作为语言保证；需要把修改拆成独立语句，再计算结果。']);
M('constptr','c-pointerconst','下面哪条语句满足类型限定？其他变量如代码所示。','int a=1,b=2;\nconst int *p=&a;\nint *const q=&a;',['p=&b;','*p=3;','q=&b;','p++; *p=3;'],['const int *p 的目标只读，但 p 本身可修改，所以 p=&b 合法。','int *const q 限定的是 q 本身，不能改 q 的地址；*q=3 则合法。','*p=3 违反目标 const。p++ 若到尾后本身可形成，但随后写 *p 同时有越界与 const 问题。']);
M('alloc-overflow','c-heap','n 为 size_t，elem_size>0。为了避免 malloc(n*elem_size) 的乘法先回绕，必须先检查哪项？','/* n 和 elem_size 来自输入 */',['n > SIZE_MAX / elem_size','n * elem_size > SIZE_MAX','n > elem_size','malloc 失败后重试即可'],['无符号乘法回绕有定义，但可能把很大的申请量变成很小的量。','先做除法比较 n>SIZE_MAX/elem_size，避免在检查时就执行可能回绕的乘法。','乘完再和 SIZE_MAX 比较永远不能发现这种回绕；申请成功也不表示容量满足原始需求。']);
M('ctor-order','cpp-ctor','C++17，下面构造打印的顺序是什么？假设输出函数本身正常。','struct T { T(int x){ std::cout<<x; } };\nstruct S {\n    T a,b;\n    S():b(2),a(1){}\n};\nS s;',['12','21','编译错误','每次运行顺序不同'],['非静态数据成员按在类中声明的顺序初始化，不按初始化列表的书写顺序。','a 声明在 b 前，所以先构造 a(1)，再构造 b(2)，打印 12。','初始化列表写反容易掩盖依赖错误，例如用尚未初始化的成员计算另一个成员。']);
M('virtual-delete','cpp-virtual','C++17，以下 delete 的语言行为是什么？','struct Base { ~Base(){} };\nstruct Derived:Base { ~Derived(){} };\nBase *p=new Derived;\ndelete p;',['未定义行为','保证只调用 Base 析构且行为正确','保证先 Derived 再 Base','一定编译错误'],['实际对象是 Derived，却通过 Base* 删除；Base 析构不是 virtual。','在该 C++17 条件下行为未定义，不能把“只调用基类析构”当作规范保证。','若基类用于多态删除，应使用 virtual ~Base()=default；派生析构随后会按正确顺序执行。']);
M('slicing-call','cpp-slicing','C++17，这段代码打印什么？','struct B { virtual int f(){return 1;} };\nstruct D:B { int f() override {return 2;} };\nD d;\nB b=d;\nB &r=d;\nstd::cout<<b.f()<<r.f();',['12','22','11','21'],['B b=d 创建了一个独立 B 对象，只复制基类部分，派生部分被切片。','b 的动态类型为 B，所以 b.f() 返回 1。','r 是绑定到 d 的引用，没有创建新对象，虚调用按 d 的动态类型返回 2。']);
M('vector-invalid','cpp-container','push_back 导致容量从1扩张后，哪种访问方式有效？','std::vector<int> v;\nv.reserve(1); v.push_back(5);\nint *p=&v[0];\nv.push_back(8); // 题设：本次确实发生重分配',['重新取得 &v[0] 后访问','通过旧 p 读取第一项','旧 p+1 保证指向第二项','reserve 后所有指针永久有效'],['重分配把元素放到新的存储空间，旧指针、引用和迭代器失效。','原来 p 的数值不会自动更新，继续解引用不再是有效的元素访问。','需要重新从 v 获取指针；reserve 只在容量未被突破时降低重分配频率，不保证永久有效。']);
M('copy-owner','cpp-copy','一个类持有 new[] 分配的独占缓冲区，但使用默认复制构造。最直接的风险是？','struct Buffer {\n    char *p;\n    Buffer():p(new char[16]){}\n    ~Buffer(){delete[] p;}\n};\nBuffer a;\n{ Buffer b=a; }',['两个对象共享地址，随后可能重复释放','默认复制会自动深拷贝16字节','析构函数禁止所有复制','char* 会自动引用计数'],['默认复制按成员复制，p 的地址值被复制，缓冲区内容没有独立复制。','b 析构后释放该块，a.p 悬空；a 析构时再次 delete[] 产生未定义行为。','可以禁用复制、实现深拷贝并处理赋值，或优先使用 vector/unique_ptr 等表达所有权。']);
M('heap-space','ds-heap','读取 n 个数，维护大小最多 k 的最小堆以保留前 k 大，k>=2。时间与额外空间上界是？','/* 每个新数与堆顶比较，必要时替换堆顶 */',['O(n log k)、O(k)','O(nk)、O(1)','O(n log n)、O(n) 才可能实现','O(log n)、O(k)'],['堆顶是当前保留集合中的最小者；只有更大的新元素需要进入集合。','插入或替换最多调整 log k 层，n 次处理得到 O(n log k) 上界。','只保留 k 个元素，空间 O(k)。这与完整排序不同，适合不能保存全部输入的流式数据。']);
M('bst-global','ds-tree','节点关系如下，是否是严格二叉搜索树？','根=10\n左子=5，右子=15\n节点5的右子=12',['不是，12 违反根节点左子树上界','是，每个直接子节点都满足大小关系','是，12>5 即可','必须是完全二叉树才可判断'],['12 虽然大于其父节点 5，却属于根 10 的整个左子树。','严格 BST 要求根左子树中的所有节点都小于 10；12 违反该全局约束。','只比较直接父子不够；递归需要传递上下界，或检查中序序列严格递增。']);
M('lowerbound-edge','ds-lowerbound','这个查找第一个 >=x 的函数存在什么问题？','size_t lo=0,hi=n;\nwhile(lo<hi){\n    size_t mid=lo+(hi-lo)/2;\n    if(a[mid]>=x) hi=mid;\n    else lo=mid; // 注意这一行\n}',['可能不终止，应改为 lo=mid+1','总是越界，应改 hi=n-1','只有数组重复才会失败','正确且总能终止'],['当 hi=lo+1 时 mid=lo。若 a[mid]<x，lo=mid 不会改变任何边界。','例如数组 [1]，x=2，会一直重复 lo=0、hi=1。','此时 mid 已被排除，必须 lo=mid+1。半开区间 hi=n 合法，循环内 mid 始终小于 hi。']);
M('complexity-triangle','ds-complexity','以下总迭代次数的渐近复杂度是？','for(size_t i=1;i<=n;++i)\n    for(size_t j=0;j<i;++j)\n        work(); // O(1)，假设循环计数不会溢出',['Θ(n²)','Θ(n)','Θ(n log n)','Θ(2^n)'],['第 i 轮内层执行 i 次，总数为 1+2+...+n=n(n+1)/2。','主导项是 n²，因此紧确界为 Θ(n²)。','两层循环并不总是平方，需要先算内层的实际范围；本题是三角形求和。']);
M('quick-worst','ds-sort','普通快速排序每次选择首元素作为 pivot，输入已升序且元素互异。时间和递归栈最坏为？','/* 每次仅按 pivot 分为较小与较大部分 */',['O(n²)、O(n)','O(n log n)、O(log n)','O(n)、O(1)','O(n²)、O(1)'],['首元素每次都是最小者，分区形成 0 个与 n-1 个元素。','每层扫描当前区间，代价 n+(n-1)+...+1，为 O(n²)。','若两侧都按普通递归调用，深度达 n，栈 O(n)。随机选主元改善期望时间，仍不消除所有最坏情况。']);
M('binary-timeout','ds-dp','面额 [1,3,4]，目标6，每种无限个。按最大面额优先的贪心解与最优解分别用几枚？','/* 只求最少枚数 */',['贪心3枚，最优2枚','贪心2枚，最优2枚','贪心3枚，最优3枚','贪心无解，最优2枚'],['贪心先拿 4，再拿 1、1，共 3 枚。','3+3 只需要 2 枚，所以贪心不保证最少。','可令 dp[s] 表示组成 s 的最少枚数，枚举最后一枚面额，从更小金额转移。']);
M('uart-budget','p-throughput','UART 115200 bit/s，8N1。每帧50字节，每秒200帧；忽略间隔。链路占用率约为？','/* 8数据位+1起始位+1停止位，无校验 */',['86.8%','69.4%','8.68%','超过100%'],['每字节上线占 10 bit，帧长 50×10=500 bit。','每秒需要 200×500=100000 bit，占 100000/115200≈86.8%。','只算 8 个数据位会低估开销；还有帧间隔时占用更高，平均可行也不等于突发不会溢出。']);
M('spi-edge','p-spi','CPOL=1、CPHA=0，哪个描述正确？','/* 片选有效期间，SCK 从空闲电平开始 */',['空闲高，首个下降沿采样','空闲低，首个上升沿采样','空闲高，第二个上升沿采样','空闲低，第二个下降沿采样'],['CPOL=1 表示空闲高；从高开始的第一个有效边沿是下降沿。','CPHA=0 表示第一个有效边沿采样，所以属于模式 2。','第二个上升沿采样对应模式 3；其余空闲低的描述不符合 CPOL=1。']);
M('can-arbitration','p-can','经典 CAN：标准数据帧 ID 0x120 与 ID 0x123 同时开始，帧类型相同。谁赢？','/* 显性位0覆盖隐性位1；按标识符高位先发 */',['0x120，首次分歧处发送显性0','0x123，数值大优先','两帧都立即报错并丢弃','无法判断，取决于载荷首字节'],['相同前缀位同时发送，第一次不同的标识符位才决定仲裁。','0x120 在首次分歧处发 0，0x123 发 1；总线上读取到 0，因此 0x123 退出仲裁。','仲裁失败不是总线错误，失败者稍后重发。标准/扩展、数据/远程混合时还要看仲裁字段，不能只比较数字 ID。']);
M('crc-vs-xor','p-crc','两个不同字节的同一位各翻转一次，原逐字节 XOR 校验会如何？','/* 校验 = payload[0] ^ payload[1] ^ ... */',['这组变化可相互抵消而漏检','保证检测全部双位错误','校验值必然改变','XOR 与任意 CRC 的检错能力相同'],['同一位翻转两次，在 XOR 累积中等价于异或同一掩码两次，结果回到原值。','所以该双位变化可漏检；校验通过只说明符合校验关系。','CRC 的能力取决于多项式和报文长度；不能笼统说任何 CRC 都发现所有错误。']);
M('timer-clock','stm32-timer','STM32F407：HCLK=168MHz，APB1分频4，TIM2采用内部时钟，PSC=83，ARR=999，向上计数。更新周期？','/* 此题固定 F407 的 APB 定时器倍频规则 */',['1ms','2ms','0.5ms','约0.994ms'],['PCLK1=168/4=42MHz；APB 分频不为1时，此芯片对应定时器时钟为 2×PCLK1=84MHz。','计数频率=84MHz/(PSC+1)=1MHz；每个计数 1μs。','周期=(ARR+1)×1μs=1000μs=1ms。漏掉倍频会算成2ms；PSC/ARR 都应加1。']);
M('dma-overrun','stm32-uartdma','UART DMA 环形接收有128字节，ISR只通知任务“有数据”。任务长时间不运行，写指针转一整圈回到原位置。最准确判断？','/* 只存模128的读写下标，无圈数和溢出标记 */',['同样的下标不能证明没有新数据，可能已覆盖','DMA 会自动保留全部历史数据','读写下标相同必然表示从未收到数据','使用 volatile 下标即可恢复丢失字节'],['模容量的下标无法区分没前进与前进恰好一圈；二者位置相同。','DMA 不会自动排队历史数据，生产快于消费时可覆盖未处理字节。','需要定义容量、处理时限与溢出检测策略，必要时统计半满/全满事件、圈数或采用双缓冲；volatile 不能恢复被覆盖内容。']);
M('watchdog','stm32-watchdog','窗口看门狗设定只能在规定窗口喂狗。把喂狗放到每次主循环入口可能怎样？','/* 已知主循环耗时变化很大 */',['过早和过晚都可能触发复位','越频繁喂狗越安全','只要代码进入循环就永不复位','提高任务优先级一定消除风险'],['窗口看门狗不只检查超时，还检查喂狗是否过早。','非常快的一次循环可能在窗口尚未开放时喂狗；很慢的一次又可能超过下界。','应根据芯片窗口计数规则设计喂狗时机，并只在关键任务健康时喂狗，不能无条件追求频繁。']);
M('stop-clock','stm32-lowpower','STM32L476 采用 STOP1，原先使用 PLL 高速时钟；按 RM0351 唤醒配置返回后，UART 波特率异常。首先核查？','/* 假设 UART 初始化参数未主动改写 */',['唤醒时钟源、PLL恢复与 UART 实际内核时钟','只修改 printf 格式','STOP1 不影响任何时钟','把接收指针改成64位'],['STOP1 停止部分时钟；唤醒采用的时钟由对应配置决定，不能直接假定已恢复原高速 PLL。','核查电源/时钟标志、重新启动与等待 PLL 稳定、切换系统时钟，再核对 UART 时钟与分频。','实际时钟改变而分频未匹配，波特率会改变；字符串格式和指针位数不能解释这类时序异常。']);
M('queue-copy','r-queue','队列元素大小为 sizeof(int)。发送成功后，接收者得到哪个值？','int x=10;\nxQueueSend(q,&x,0); // 假设成功\nx=99;\n/* 然后从 q 接收一个 int */',['10','99','&x 的数值','取决于 int* 是否 volatile'],['队列按创建时的元素大小，把发送地址上的数据复制进内部存储。','该队列存 int，不是 int*；发送成功时拷贝的值为 10。','之后 x=99 只改变源变量。若队列元素设为指针，则复制的是地址，访问与生命周期规则会不同。']);
M('priority-inheritance','r-mutex','FreeRTOS：H优先级3，M为2，L为1；L持有mutex，H请求后阻塞，M已就绪。使用支持优先级继承的mutex时首先谁执行？','/* 单核、抢占式调度，忽略其他任务与中断 */',['L 临时继承优先级3并执行','M 一直优先于 L','H 继续执行并占满CPU','L 自动被删除'],['H 被 mutex 阻塞后不能运行；如果 L 保持优先级1，M会阻挡 L 释放锁，形成优先级反转。','mutex 使持锁者 L 临时继承 H 的优先级，于是 L 优先于 M，推进临界区并释放锁。','H不会因为等待锁继续运行。复杂多锁场景中的继承/解除要看内核规则，不能把机制理解为提高所有低优先级任务。']);
M('delay-drift','r-delay','假设周期任务第一次 t=0 开始，每次处理3 tick，再 vTaskDelay(10)。第二、三次开始时间？','for(;;){ work_for_3_ticks(); vTaskDelay(10); }\n/* 忽略调度延迟，延时恰好10 tick */',['13、26','10、20','3、6','10、23'],['vTaskDelay 的相对延时从调用时算起，第一次调用发生在 t=3。','第一次再等10 tick，到 t=13；处理到16，再等10，到26。','每次起点间隔是处理时间+延时。固定周期通常使用 xTaskDelayUntil 并考虑超期，而不是每次工作后再相对等一个周期。']);
M('isr-priority','r-isr','Cortex-M 的 FreeRTOS 移植：某ISR的数值优先级小于允许调用内核 API 的阈值。ISR内想发队列，该怎么办？','/* 数值越小通常代表中断紧急程度越高；按所用移植层配置解释 */',['调整到允许范围或先交给可调用API的低紧急程度上下文','改为普通 xQueueSend 就可以','只要名字有 FromISR 就不受优先级限制','把ISR内局部变量设为 static 就可以'],['FromISR 区分中断接口，并不取消中断优先级约束。','过高紧急程度的 ISR 可能不被内核临界区屏蔽，直接操作内核结构会破坏一致性。','应核对逻辑优先级与寄存器编码阈值；使用适当中断优先级或安全的延后处理，不能在 ISR 调普通阻塞 API。']);
M('event-loss','r-eventloss','ISR每次将标志 pending=1，任务处理后清零。连续3次事件在任务运行前到达，会怎样？','volatile int pending;\n/* ISR: pending=1;\n   task: if(pending){ pending=0; process_once(); } */',['可能合并成一次处理，还存在读清竞态','volatile 自动保存3次计数','一定处理3次','单核意味着绝无竞态'],['1、1、1 写入同一标志最终仍是1，不能表达事件次数。','任务检查与清零之间也可能插入 ISR；新事件会被后续清零覆盖。','需要计数语义时用计数通知、计数信号量或队列，并分析饱和/溢出；volatile 不提供计数或原子读改写。']);
M('deadlock-order','os-deadlock','T1先锁A再锁B，T2先锁B再锁A。哪项能针对循环等待给出明确预防？','/* 两个不可递归 mutex */',['所有任务统一按A再B的顺序获取','只把两任务优先级设相同','把锁变量声明 volatile','仅提高 T1 优先级'],['当 T1持A等B、T2持B等A，就形成循环等待。','全局统一锁序可以禁止这种环：两任务都先A再B，不能出现互相占有对方前置锁。','优先级和 volatile 不改变锁依赖；超时可做恢复策略，但必须释放已持资源，不能单靠重试。']);
M('atomic-inc','os-sync','两个任务并发执行共享 count++，初始0，每个执行一次。没有同步，哪项最准确？','int count=0;\n/* 两个线程/任务均执行 count++ */',['存在竞态；C线程模型中非原子数据竞争是未定义行为','保证最后为2','volatile 后保证为2','32位CPU意味着整个 ++ 必然原子'],['++ 包含读取、加法、写回，不因变量宽度为32位就自动成为原子读改写。','两次读取相同旧值后写回，会在实际机器中出现丢更新；但不能把某个值当作 C 数据竞争程序的语言保证。','使用合适的 mutex、临界区或真正原子操作。volatile 仅影响访问，不替代同步。']);
M('stack-depth','mem-stack','递归每层至少新增80字节栈，任务可用栈剩余1024字节，递归深度20。忽略其他开销，判断？','/* 每层栈帧都同时存活，未作尾调用优化 */',['至少需1600字节，已超过预算','只需80字节','调用结束会释放，因此无需预算','剩余1024字节总能支持1024层'],['递归下降时前一层尚未返回，栈帧同时存在。','20×80=1600，已超过1024；真实还可能有调用、保存寄存器、中断等额外开销。','结束后释放不解决递归峰值问题。需要限制深度、改迭代或调整栈，并测量高水位。']);
M('startup-data','mem-startup','全局 initialized=7 与 zero 未显式初始化，链接到 SRAM 的 .data 与 .bss。复位启动代码应做什么？','int initialized=7;\nint zero;',['从Flash复制.data初值到SRAM，并清零.bss','只清零二者','SRAM掉电后仍自动保存7','无需初始化，C自动补成正确值'],['编译/链接把 .data 的初始镜像放在非易失存储中，运行地址则可能在 SRAM。','在进入 C 程序前，启动代码按链接器符号复制 .data，并把 .bss 清为零。','两块都清零会丢失7；普通 SRAM 不能作为复位后初值的可靠来源。具体启动流程取决于工具链和链接脚本。']);
M('thumb-call','arm-assembly','Thumb 函数中执行 BL helper 之后还想按原LR返回，下面核心问题是什么？','func:\n    BL helper\n    BX LR',['BL 改写LR，必须保存并恢复原返回地址','BX LR 一定跳回最初调用者','BL 只改变R0','LR 是硬件只读寄存器'],['进入 func 时 LR 保存调用者的返回地址；BL helper 会写入新的返回地址。','helper 返回后 LR 仍指向 func 内 BL 后的位置，直接 BX LR 无法使用原来的调用者地址。','通常通过栈或合适寄存器保存旧 LR，再恢复，例如 PUSH {LR} / ... / POP {PC}；真实函数还需遵守ABI栈对齐。']);
M('nvic-number','arm-interrupt','在采用常见 Cortex-M NVIC 优先级表示的题设中，优先级数值2和5都可抢占当前线程，哪一个更紧急？','/* 假设同一优先级分组且差异落在抢占字段 */',['数值2','数值5','数字一样才可中断','由任务优先级决定'],['NVIC 通常用较小的优先级数值表示较高的紧急程度，所以2比5紧急。','FreeRTOS 任务优先级通常是数值越大越高，不能混用两套方向。','还应区分已实现位数、分组和寄存器左移编码；题目已限定差异在抢占字段。']);
M('tcp-stream','n-tcpudp','TCP发送方分两次 send，共写入200字节。接收方能否靠一次 recv 等于一帧判断？','/* 假设无错误，数据最终全部送达 */',['不能，需要长度/分隔符等应用层分帧','TCP保证每次recv对应一次send','每次recv必定返回200字节','TCP可靠，所以无需处理短读'],['TCP提供有序字节流，保留字节顺序，不保留 send 调用边界。','接收可能一次拿到部分、一个或多个应用报文，因此必须积累数据再按长度等规则拆帧。','可靠传输不等于一次读满；还需处理连接关闭、错误和非法长度。']);
M('debug-evidence','e-debug','偶发 HardFault，只在高负载出现。最有助于从地址定位故障的一组现场是？','/* 有可匹配固件版本的 ELF/map 文件 */',['异常堆栈PC/LR与故障状态寄存器、栈范围','只打印“进入了HardFault”','先永久关掉全部中断','只把所有变量改 volatile'],['堆栈 PC 帮助定位出错指令，LR/异常返回值与堆栈选择帮助还原调用和异常路径。','CFSR/HFSR 等故障状态以及在有效时的地址寄存器，可区分非法访问、总线错误等线索。','结合正确版本的 ELF/map、栈边界检查；只有一句日志缺少定位证据，全面关中断会改变触发条件。']);
M('project-load','pr-watch','屏幕刷新通过 SPI 同步发送大块数据；高优先级传感器任务也需要同一总线。首先怎样分析响应时间？','/* 总线用 mutex 保护，刷新任务较低优先级 */',['测量最长持锁时间并考虑分块/异步传输与锁设计','仅提高传感器优先级就保证零延迟','mutex 自动让所有临界区耗时为0','提高SPI时钟无需核对屏幕时序'],['高优先级任务遇到已持有的总线锁会阻塞，提升优先级不会让传输自动完成。','优先级继承帮助持锁者推进，却不能消除最长事务时间；需测量持锁时长与截止时间。','可评估分块、DMA与异步完成，但DMA缓冲生命周期和总线释放时机要明确，且时钟必须满足器件要求。']);
M('project-state','pr-sorter','分拣动作A结束后动作B开始，A的旧超时事件延后到达。怎样避免它使B误入故障？','/* 事件由同一控制任务处理 */',['事件携带操作编号，核对当前编号与状态','只取消定时器，无需检查已入队事件','忽略所有超时','每个传感器回调直接改全局状态'],['取消定时器不保证之前已投递到队列的事件消失。','启动操作时分配编号，超时带该编号；控制任务只接受与当前操作、状态匹配的超时。','这能丢弃A的过期事件同时保留B的真实超时；忽略所有超时会失去故障保护。']);
W('ptr-trace','c-pointer','代码阅读','三种 ++ 与 * 的结合','逐行填写 a、b、c、p 的最终指向，以及数组内容。假设数组访问均有效。','int v[]={3,6,9};\nint *p=v;\nint a=*p++;\nint b=(*p)++;\nint c=*++p;','a=3，b=6，c=9；p=&v[2]；v={3,7,9}。',['第一行 *(p++) 先取 v[0]=3，随后 p 指向 v[1]。','(*p)++ 增加目标值：b取得旧值6，v[1]变7，p不移动。','*++p 先把 p移到 v[2]，再读取9。每行只有一个 ++，按独立语句逐行算。'],['a、b、c 各1分','最终p和数组各1分','说明指针移动与值修改的区别2分']);
W('array-address','c-array','填空计算','a、&a、a+1、&a+1','int为4字节，a首地址示意为0x1000。填写 a+1、&a+1 的地址及各自指针目标类型。','int a[5]={0};','a+1 为0x1004，类型 int*；&a+1 为0x1014，类型 int (*)[5]。',['a 用在加法中转换成首元素地址，跨过一个int即4字节。','&a取得整个数组的地址，跨过整个数组20字节。','两种起始地址数值可相同，类型不同导致步长不同；尾后地址可形成但不能解引用。'],['两个地址各2分','两个类型各1分','说明尾后指针不可解引用2分']);
W('doubleptr','c-doubleptr','找错改错','为什么函数没有更新调用者指针','找出失败原因，使用二级指针给出修复；补充申请失败与释放责任。','void make(int *p){ p=malloc(sizeof *p); }\nint *x=NULL;\nmake(x);','p 是 x 地址值的一份副本。修复为 bool make(int **out){ if(!out)return false; *out=malloc(sizeof **out); return *out!=NULL; }，调用 make(&x)，使用后 free(x)。',['把NULL值复制给形参p，不会建立对变量x本身的引用。','p=malloc 只改局部p，申请的地址丢失还会泄漏。','传&x让函数通过*out改x；接口需约定原指针为空，或明确旧对象所有权，避免覆盖造成泄漏。'],['按值传递原因2分','二级指针修复3分','失败检查和释放责任2分']);
W('strlen-size','c-string','填空计算','数组、指针与字符串终止符','假设 char1字节、指针4字节。填写四处结果并解释。','char a[]="hello";\nchar *p=a;\nsizeof(a); sizeof(p); strlen(a); sizeof(*p);','6、4、5、1。',['a含5个文字字符加结尾零，共6。','p是指针变量，本题指针4字节；sizeof(p)不读取整串。','strlen计数到首个零之前，为5；*p类型char，sizeof(*p)=1。'],['四个结果各1分','说明终止符与目标类型2分']);
W('padding-reorder','c-struct','填空计算','重排结构体降低填充','给定char1/对齐1、short2/对齐2、int4/对齐4，无打包。算原大小，再通过重排降到8字节，说明代价。','struct S { char a; int b; short c; };','原偏移0、4、8，大小12；重排 int b; short c; char a; 后偏移0、4、6，尾补1，大小8。',['先按每个成员的对齐把偏移向上补齐，最后按整体对齐补齐总长。','大对齐成员放前面可在此例减少空洞，但并不是所有布局都可以任意更换。','若结构体用于接口ABI、文件或通信协议，重排改变布局；协议宜显式逐字节序列化。'],['原布局3分','新布局3分','说明ABI/协议影响2分']);
W('memcpy-overlap','c-memcpy','找错改错','移除数组首元素的陷阱','找出复制与长度问题，给出安全写法。n表示有效元素个数，n<=capacity，a可读写。','memcpy(a,a+1,(n-1)*sizeof *a);','n=0 会使无符号 n-1 回绕；重叠区使用 memcpy 违反要求。先 if(n>0) memmove(a,a+1,(n-1)*sizeof *a); 再更新有效长度。',['对n=0先判断，不先计算n-1。','源与目标范围通常重叠，memmove提供重叠复制语义。','本题保证有效数组容量；通用接口还需确认字节乘法不回绕、指针有效、调用者同步维护长度。'],['空数组回绕2分','重叠原因2分','memmove修复与长度更新2分']);
W('macro-repeat','c-macro','找错改错','加括号仍没有修好的宏','说明 MIN(i++,j++) 为什么不安全，不给它推定一个唯一输出；提供避免重复求值的方法。','#define MIN(a,b) ((a)<(b)?(a):(b))','比较先对两个实参各求值一次，选中的分支还会再求值该实参；宏不是一次求值的函数。使用类型合适的函数，先在独立语句取得参数值，再调用。',['宏有括号只能修复运算优先级，不能消除重复替换。','?:只求值选中分支，但比较中的副作用已经发生；实参副作用也让顺序分析复杂。','例如 int x=i++; int y=j++; int m=min_int(x,y);，各自只递增一次。'],['指出重复求值3分','说明括号解决范围1分','安全替代3分']);
W('bitfield','c-bits','填空计算','只修改寄存器中指定字段','假设普通可读写 uint32_t 寄存器；位[7:4]是字段，value只接受0..15。补全 mask 和更新式；解释为何不能随便用于W1C寄存器。','uint32_t mask = ____;\nreg = (reg & ____) | ____;','mask=0xFu<<4；reg=(reg & ~mask) | ((value & 0xFu)<<4)。',['先清掉目标4位，再将新值限制为4位并左移写入，其他位保持。','例如reg=0xABCD、value=2，结果0xAB2D；只用OR不能把字段中原来的1清掉。','读改写可能有并发竞态；W1C等特殊寄存器读取值再写回可能清除不想清的标志，要按手册专用规则操作。'],['掩码2分','表达式3分','W1C与并发说明2分']);
W('ub-scope','c-ub','找错改错','返回局部数组后还能用吗','找出生命周期问题，给出两种合理接口，说明线程安全与释放责任。','char *name(void){ char s[8]="MCU"; return s; }\nputs(name());','s在函数返回时生命周期结束，返回地址不能继续作为有效字符串读取。可由调用者提供缓冲区，或动态申请并约定释放；静态缓冲区可延长生命周期但共享且不可重入。',['返回的不是字符副本，而是局部对象的地址。','调用者缓冲区接口需接受容量并保证结尾零；动态接口需检查失败。','static方案不一定适合多个任务同时调用；不能用“这次还能打印”证明正确。'],['生命周期3分','两种方案各2分','线程安全/所有权2分']);
W('ctor-dtor','cpp-ctor','代码阅读','基类与成员的构造析构','C++17，写出输出顺序。解释为何初始化列表写法不决定成员顺序。','struct T{ char c; T(char x):c(x){std::cout<<c;} ~T(){std::cout<<c;} };\nstruct B{ T t; B():t(\'B\'){} };\nstruct D:B{ T x,y; D():y(\'Y\'),x(\'X\'){} };\n{ D d; }','BXY YXB（连续输出 BXYYXB）。',['先构造基类B，其中t打印B；随后按声明构造x再y，打印X、Y。','离开作用域时先析构派生成员，逆序y再x；再析构基类中的t，打印Y、X、B。','初始化列表y在前不改变声明顺序；完整对象释放按构造完成顺序逆序进行。'],['构造顺序3分','析构顺序3分','说明声明顺序1分']);
W('rule-five','cpp-copy','简答设计','独占资源类怎样支持复制与移动','类持有new[]缓冲区。说明复制构造、复制赋值、移动构造、移动赋值与析构的职责，以及如何处理自赋值。','','复制要建立独立缓冲区；移动转移所有权并将源清为空；析构匹配delete[]。复制赋值可用copy-and-swap提供异常安全；优先采用容器/智能指针。',['默认成员复制仅复制地址，不能表达独占资源的复制语义。','赋值还要处理目标已有资源以及申请失败；不能先释放再申请而丢失原值。','移动后源仍可析构，通常将其置为空；移动自赋值要有安全约定或显式检查。'],['复制/赋值职责3分','移动与源状态3分','自赋值和异常安全2分'],'挑战');
W('virtual-lifetime','cpp-virtual','代码阅读','构造函数中的虚调用','C++17，B构造时调用f，D构造完成后再通过引用调用，分别得到什么？','struct B{ B(){std::cout<<f();} virtual int f(){return 1;} };\nstruct D:B{ int f() override{return 2;} };\nD d; B &r=d; std::cout<<r.f();','打印12。',['B构造阶段调用虚函数，按当前正在构造的B层处理，不调用尚未构造完成的D覆盖函数。','D构造完成后，r绑定完整D对象，普通虚调用返回2。','不要在基类构造/析构依赖派生资源；纯虚函数还有额外限制，本例不是纯虚。'],['结果2分','构造阶段解释3分','完成后的动态分派2分']);
W('vector-growth','cpp-container','简答设计','为什么 vector 追加是均摊 O(1)','用容量大致倍增的模型说明均摊复杂度与单次最坏复杂度，说明标准不保证具体倍增系数。','','n次追加的整体移动次数可按1+2+4+...求和到O(n)，因此均摊O(1)；触发扩容的单次追加可为O(n)。',['多数追加只在尾部构造一个元素；少数追加需要申请新空间并迁移旧元素。','几何级数和受最大项常数倍约束，总迁移成本与n同阶。','模型用于解释均摊，不能断言所有实现恰好扩容2倍；扩容还使旧引用/迭代器失效。'],['几何级数推导3分','单次与均摊区分2分','实现和失效说明2分']);
W('binary-duplicate','ds-lowerbound','填空计算','手推重复元素的二分边界','在[1,2,2,2,5]上找第一个>=2的位置，采用[lo,hi)。写出每轮(lo,hi,mid)和最终结果。','','(0,5,2)→hi=2；(0,2,1)→hi=1；(0,1,0)→lo=1；退出lo=hi=1。',['>=目标时不能马上返回mid，因为左侧可能还有相同值；收缩hi=mid。','<目标时mid一定不合格，可以排除并lo=mid+1。','最终返回分界1。若结果=n说明不存在>=目标者，该位置不能当元素读取。'],['三轮状态各1分','结果1分','左右更新依据3分']);
W('sort-stability','ds-sort','简答设计','稳定性为什么影响多字段排序','先按姓名排序，再按成绩稳定排序，主次顺序是什么？若第二次使用不稳定排序可能怎样？','','最终主键为成绩，相同成绩保留之前的姓名顺序，因此次键为姓名；第二次不稳定可能打乱同成绩的姓名顺序。',['后执行的排序决定主键排列。','稳定排序只承诺相等键之间保留输入顺序，本例的输入次序已由姓名排序构建。','比较器应满足排序算法的要求；稳定不是完全不移动元素，也不能只由平均复杂度推断。'],['主次键3分','稳定性理由3分','不稳定后果1分']);
W('stack-proof','ds-queue','简答设计','单调栈的嵌套 while 为什么仍是 O(n)','在找下一个更大值时，每项push一次，while可能pop很多项。用总操作数解释复杂度，不只背答案。','','每个下标至多入栈一次、出栈一次，全程push+pop不超过2n，额外比较同阶，因此O(n)，栈空间O(n)。',['某一天可让许多旧下标出栈，单轮最坏O(n)。','但被弹出的下标不会再入栈，不能在每个外层循环重复支付同一项弹出成本。','用全程总次数得到线性；遇到相等温度应保留等待更大值，比较通常为严格大于。'],['单次与总量区分2分','至多一次入出证明3分','空间与相等条件2分']);
W('deadlock-trace','os-deadlock','简答设计','画出互斥锁的等待环','T1持A等待B，T2持B等待A。写等待关系，并提出预防与超时恢复各一种，说明恢复的资源处理。','','等待环：T1→B→T2→A→T1。预防用全局统一锁序；恢复用超时撤销操作并释放已持锁，有限重试/退避。',['两任务都等另一任务释放资源，因此谁都无法到解锁语句。','统一锁序阻止形成环。只提高优先级不会解开已经形成的环。','超时后保留旧锁再立即重试仍可能维持阻塞；还要处理已执行操作的回滚/一致性。'],['等待环2分','预防2分','恢复与资源一致性3分']);
W('endian-parse','mem-endian','代码阅读','网络字节序解析与非对齐访问','缓冲区前三字节为AA 12 34。要从偏移1解析大端16位数，说明强转读取的两个独立问题并修复。','uint16_t x=*(uint16_t *)(buf+1);','目标值0x1234。强转可能非对齐，且结果依赖主机端序；应 x=((uint16_t)buf[1]<<8)|buf[2]，buf使用unsigned char/uint8_t，先确认长度至少3。',['buf+1不保证满足uint16_t对齐，一些目标可能故障；语言对象访问规则也需满足。','即便CPU能读，若主机小端会把这两字节解释为0x3412。','逐字节组合明确端序，也避免非对齐宽读取；长度校验必须在读取前。'],['对齐与端序各2分','修复2分','长度和无符号字节1分']);
W('link-sections','mem-sections','填空计算','Flash镜像与运行内存','按普通裸机链接约定，指出下列对象常在何段，哪些需要启动复制/清零；说明常量段位置不是C语言强制。','int g=7;\nstatic int z;\nconst char text[]="OK";\nvoid f(void){ int local=1; }','g常在.data，z常在.bss，text常在.rodata，local常在栈或寄存器；.data复制初值，.bss清零。',['区分存储持续期、可写性、初值以及链接器布局。','local可能被优化到寄存器或完全消除，不能认为源码中每个变量都有栈地址。','const限定语言上的修改，具体放Flash/SRAM由工具链和链接脚本决定。'],['四个对象4分','启动行为2分','平台与优化条件2分']);
W('timer-formula','stm32-timer','填空计算','从时钟树推导定时器参数','F407：HCLK=168MHz，APB1分频4，TIM2内部时钟。要1MHz计数、每20ms更新，填PSC、ARR并说明加1来源。','','TIM2时钟84MHz；PSC=83，ARR=19999。',['APB1为42MHz，对应定时器倍频为84MHz。','除数是PSC+1，所以84MHz/1MHz=84，PSC=83。','向上计数从0到ARR包含ARR+1个计数，20ms×1MHz=20000，ARR=19999。'],['时钟2分','PSC/ARR各2分','解释加1两处2分']);
W('dma-owner','stm32-dma','简答设计','DMA发送期间能复用缓冲区吗','启动DMA发送后函数立即返回，随后同一buffer写入下一帧。解释接收可能混帧的原因，提出安全方案。','','DMA异步读取原buffer，未完成前修改可能混入新帧数据。用完成事件转移所有权，或双缓冲/固定池；避免发送指向已结束生命周期的局部数组。',['返回成功通常表示提交成功，不等于硬件已读完全部字节。','生产者必须知道哪块正在DMA使用、哪块可填充；完成/失败/取消均有明确回收路径。','带D-cache的芯片还需按器件手册处理缓存一致性；不能把F407情况套到所有STM32。'],['异步读取原因3分','完成与缓冲方案3分','生命周期/失败处理2分']);
W('uart-loss','p-uart','填空计算','算接收缓冲区可以撑多久','UART115200、8N1连续接收，缓冲512字节。最多多少毫秒不消费才会填满？工程上为什么不能按该极限安排？','','字节速率11520B/s，512/11520≈44.44ms。必须留裕量并考虑已积压字节、调度抖动和处理耗时。',['每字节线上10bit，先从bit/s换成byte/s。','容量除以字节速率得到理想填满时间。','这是初始为空且无额外机制的预算；实际须约定溢出与背压，测量最坏响应，不只测平均。'],['字节速率2分','时间2分','预算前提与裕量3分']);
W('spi-trace','p-spi','填空计算','用边沿顺序确定SPI模式','空闲高，从片选有效后观察到下降、上升、下降、上升；接收方在第1、3个边沿采样。填CPOL、CPHA、模式与首次采样前的数据条件。','','CPOL=1，CPHA=0，模式2；首位数据需在第一个下降沿之前满足建立时间，并在采样后满足保持时间。',['空闲电平给出CPOL=1。','每周期第一个边沿采样，对应CPHA=0；下降沿是此电平下的第一边沿。','只答模式号不足以保证通信；首位预装载、片选建立时间和从机时序还需满足手册。'],['三个参数3分','边沿解释2分','建立/保持与片选2分']);
W('queue-dangling','r-queue','找错改错','队列成功也可能传出悬空指针','队列元素为char*，找出问题并给出两种修复路径；区分&ptr与ptr。','void produce(void){\n    char buf[32]="sample";\n    char *ptr=buf;\n    xQueueSend(q,&ptr,0);\n}','队列复制ptr的地址值，不复制32字节；produce返回后buf失效。可改队列存固定大小数据副本，或从池取得持久缓冲并在发送成功后移交所有权。',['指针队列发送&ptr，是让队列从ptr变量地址复制sizeof(char*)字节；发送ptr会误把数据前几个字节当指针值。','发送成功只保证地址被复制，不能延长局部buf生命周期。','池方案发送失败生产者回收，消费完成消费者归还；不要为避免悬空而制造永久泄漏。'],['生命周期与值复制3分','两种修复3分','&ptr/ptr与失败回收2分']);
W('schedule-trace','r-task','填空计算','就绪与阻塞决定谁能运行','单核抢占式：A优先级3，B为2，C为1。t0三者就绪；t1 A阻塞于队列；t2 B延时；t3 ISR唤醒A并请求切换。各时刻谁运行？','','t0 A，t1 B，t2 C，t3退出ISR后A。',['只在就绪集合里选最高优先级；阻塞任务不会因优先级高继续占CPU。','A等待队列时移出就绪集合，B延时后也移出。','ISR发送数据使A就绪；正确请求切换后在中断返回路径运行A，不在ISR内部直接执行任务代码。'],['四时刻4分','就绪/阻塞原因2分','中断返回切换2分']);
W('period-overrun','r-delay','简答设计','周期任务处理超过周期','期望每10tick开始一次，实际每次处理15tick。改用xTaskDelayUntil能否保证10tick周期？说明怎样设计超期策略。','','不能。固定唤醒API不能让15tick工作在10tick预算内完成；超期时可能不阻塞并尝试追赶。应测量、拆分/降低频率、跳过过期周期或记录故障，明确截止时间策略。',['区分消除相对延时漂移和保证可调度性。','超过目标唤醒时刻时，无法回到过去；具体返回/更新规则按API版本。','连续追赶可能占满CPU影响低优先级任务，要明确丢周期、降级与监控。'],['不能保证及原因3分','超期行为2分','可执行策略3分']);
W('isr-api','r-isr','找错改错','ISR中的阻塞发送与优先级','找出两类问题，并给出允许优先级内的ISR发送骨架。','void IRQ_Handler(void){\n    xQueueSend(q,&event,portMAX_DELAY);\n}','不能在ISR使用普通可能阻塞的发送；还必须满足移植层允许调用内核API的中断优先级。骨架：BaseType_t woke=pdFALSE; xQueueSendFromISR(q,&event,&woke); portYIELD_FROM_ISR(woke); 并处理队列满。',['ISR不能像任务一样进入阻塞等待空间；使用FromISR接口不带阻塞等待时间。','阈值必须核对优先级位数、逻辑值与寄存器编码。','队列满意味着发送失败，要定义丢弃/统计/延后策略；正确清中断源也需按外设手册处理。'],['接口与优先级两类错误4分','骨架2分','队列满和中断源2分']);
W('hardfault','e-debug','简答设计','一次HardFault怎样收集可用现场','准备一个最小诊断方案，说明MSP/PSP选择、异常堆栈PC、故障寄存器及ELF版本对应关系。','','根据EXC_RETURN选择异常所用栈；按实际堆栈格式取PC/LR，读取故障状态，确认地址寄存器有效位；用匹配固件的ELF反汇编/符号定位。',['先判断堆栈本身是否可访问，栈溢出时盲读或调用printf可能再次故障。','Cortex-M硬件基本异常帧包含R0-R3、R12、LR、PC、xPSR；浮点/堆栈异常需按内核具体格式处理。','保存最小固定现场，避免动态申请和复杂阻塞；map/ELF必须和运行固件一致，否则符号定位会错。'],['栈选择与格式3分','寄存器和有效性3分','版本与二次故障2分'],'挑战');
W('tcp-framing','n-tcpudp','简答设计','长度前缀协议怎样处理半包和连包','协议为2字节大端长度+载荷，长度最大1024。设计持续输入解析器，描述长度不足、载荷不足、多帧与非法长度。','','积累2字节头后解码长度并校验上限，等待完整载荷，交付后继续处理剩余字节；非法长度/超时按协议关闭或可靠重同步。',['每次recv长度不代表报文边界，保存当前头与载荷进度。','先验长度，再申请/索引；还要覆盖0长度约定和不可信输入。','一个输入批次可能包含多帧，交付一帧后不能直接丢掉剩余字节。'],['半包与连包3分','长度校验2分','超时/重同步/零长度2分']);
W('return-register','arm-register','代码阅读','AAPCS32的参数与返回值','按AAPCS32，函数f(int a,int b,int c,int d,int e)五个整数参数一般怎样传递？普通32位整数返回值在哪里？不要把该规则套到任意ABI。','','前四个参数通常在R0-R3，第五个通过栈传入；32位整数返回值通常在R0。',['调用者根据ABI准备寄存器和栈；被调用者按同一约定解释。','实际栈偏移取决于函数序言和保存寄存器，不能只看一张寄存器表猜偏移。','浮点、64位值、结构体返回等有额外规则；本题限定五个普通32位整数。'],['五参数位置3分','返回值1分','栈偏移和适用范围2分']);
W('project-budget','pr-robot','简答设计','周期控制任务的最坏时间预算','控制周期5ms；采样1ms、控制计算1.5ms、输出0.5ms；可能被ISR累计占用1.2ms，还可能等待锁1ms。是否满足单周期预算？','','合计5.2ms，已超过5ms，不能由平均3ms处理时间宣称满足；需降低阻塞/干扰、调整周期或拆分，并测量最坏路径。',['任务自身工作共3ms，不包含被抢占和锁阻塞。','加入干扰1.2ms与阻塞1ms，总响应时间至少预算5.2ms。','实际调度分析还要考虑释放抖动、任务相互干扰和中断到达模型；题设的简单加法已足以发现预算不满足。'],['总和与判断3分','工作时间/响应时间区分2分','改进与验证2分'],'挑战');

